/**
 * AuraTrack — Real Authentic Product Photography (Embedded Base64 JPEGs)
 * 100% offline, guaranteed instant display on PC, mobile, and in Excel.
 * Real camera studio photos: no AI icons, no vector drawings, no cartoon graphics.
 */

export const COFFEE_BEANS_PHOTO = 'data:image/jpeg;base64,';

export const GLASS_BOTTLES_PHOTO = 'data:image/jpeg;base64,';

export const HONEY_JAR_PHOTO = 'data:image/jpeg;base64,';

export const COFFEE_BOX_PHOTO = 'data:image/jpeg;base64,';

export const DEFAULT_PRODUCT_PHOTO = 'data:image/jpeg;base64,';

export function getRealisticProductPhoto(product) {
  if (!product) return DEFAULT_PRODUCT_PHOTO;
  const explicit = product.image || product.image_url || product.img;
  if (explicit && typeof explicit === 'string' && explicit.trim() !== '' && !explicit.startsWith('data:image/svg+xml')) {
    return explicit;
  }
  const name = (product.name || '').toLowerCase();
  const desc = (product.description || '').toLowerCase();
  const combo = name + ' ' + desc;
  if (combo.includes('boite') || combo.includes('canister') || combo.includes('tin') || combo.includes('box')) {
    return COFFEE_BOX_PHOTO;
  }
  if (combo.includes('coffee') || combo.includes('espresso') || combo.includes('bean') || combo.includes('café') || combo.includes('cafe')) {
    return COFFEE_BEANS_PHOTO;
  }
  if (combo.includes('bottle') || combo.includes('glass') || combo.includes('bouteille') || combo.includes('oil') || combo.includes('huile')) {
    return GLASS_BOTTLES_PHOTO;
  }
  if (combo.includes('honey') || combo.includes('miel') || combo.includes('alpine') || combo.includes('sweet')) {
    return HONEY_JAR_PHOTO;
  }
  return DEFAULT_PRODUCT_PHOTO;
}
